function QuenchTankDrainValveMaker.init() QuenchTankDrainValveMaker.ironStock=14; QuenchTankDrainValveMaker.bronzeStock=12; QuenchTankDrainValveMaker.woodStock=12; QuenchTankDrainValveMaker.leatherStock=8; QuenchTankDrainValveMaker.silverStock=8; QuenchTankDrainValveMaker.goldStock=6; QuenchTankDrainValveMaker.jewelStock=4; QuenchTankDrainValveMaker.pearlStock=4; QuenchTankDrainValveMaker.productStock={}; QuenchTankDrainValveMaker.buildings={}; QuenchTankDrainValveMaker.maker=nil; QuenchTankDrainValveMaker.activeMaking={}; QuenchTankDrainValveMaker.totalProducts=0; QuenchTankDrainValveMaker.dayTimer=0; print("[QuenchTankDrainValveMaker] Royal Quench Tank Drain Valve Maker System initialized (6 products, 4 buildings)") end
function QuenchTankDrainValveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuenchTankDrainValveMaker.maker={name=n or ("Zaklopkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopkar najet: %s (spretnost: %d)",QuenchTankDrainValveMaker.maker.name,s),"success") end; return true end
function QuenchTankDrainValveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuenchTankDrainValveMaker.build(id) local ok,e=QuenchTankDrainValveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuenchTankDrainValveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuenchTankDrainValveMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuenchTankDrainValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuenchTankDrainValveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuenchTankDrainValveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuenchTankDrainValveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuenchTankDrainValveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuenchTankDrainValveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuenchTankDrainValveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuenchTankDrainValveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuenchTankDrainValveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuenchTankDrainValveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuenchTankDrainValveMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not QuenchTankDrainValveMaker.maker then return false,"Potreben zaklopkar" end; return true end
function QuenchTankDrainValveMaker.make(pt,qty) qty=qty or 1; local ok,e=QuenchTankDrainValveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuenchTankDrainValveMaker.ironStock=QuenchTankDrainValveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuenchTankDrainValveMaker.bronzeStock=QuenchTankDrainValveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuenchTankDrainValveMaker.woodStock=QuenchTankDrainValveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuenchTankDrainValveMaker.leatherStock=QuenchTankDrainValveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuenchTankDrainValveMaker.silverStock=QuenchTankDrainValveMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuenchTankDrainValveMaker.goldStock=QuenchTankDrainValveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuenchTankDrainValveMaker.jewelStock=QuenchTankDrainValveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuenchTankDrainValveMaker.pearlStock=QuenchTankDrainValveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuenchTankDrainValveMaker.maker then t=math.max(1,t-math.floor(QuenchTankDrainValveMaker.maker.skill/13)) end; table.insert(QuenchTankDrainValveMaker.activeMaking,{id="quenchtankdrainvalve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuenchTankDrainValveMaker.completeMaking(m) local q=1.0+(QuenchTankDrainValveMaker.getQualityBonus()/100); if QuenchTankDrainValveMaker.maker then q=q+(QuenchTankDrainValveMaker.maker.skill/140) end; q=math.min(2.5,q); QuenchTankDrainValveMaker.productStock[m.productType]=(QuenchTankDrainValveMaker.productStock[m.productType] or 0)+m.quantity; QuenchTankDrainValveMaker.totalProducts=QuenchTankDrainValveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuenchTankDrainValveMaker.maker then QuenchTankDrainValveMaker.maker.itemsMade=QuenchTankDrainValveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuenchTankDrainValveMaker.maker.skill=math.min(100,QuenchTankDrainValveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quenchtankdrainvalve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuenchTankDrainValveMaker.update(dt) if not _G.state then return end; QuenchTankDrainValveMaker.dayTimer=QuenchTankDrainValveMaker.dayTimer+dt; if QuenchTankDrainValveMaker.dayTimer>=30 then QuenchTankDrainValveMaker.dayTimer=0; for i=#QuenchTankDrainValveMaker.activeMaking,1,-1 do local m=QuenchTankDrainValveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuenchTankDrainValveMaker.completeMaking(m); table.remove(QuenchTankDrainValveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuenchTankDrainValveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuenchTankDrainValveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
